function P:DisplayCategory(item)
    return (self.inkIDs[item.id] or self.pigmentIDs[item.id]) and "viewer_inks" or item.categoryKey;
end

function P:MaterialRank(item)
    if self.category == "viewer_inks" then
        local data = self.materialData and self.materialData[item.id];
        local pigment = self.pigmentIDs[item.id];
        local title = pigment and "Пигменты" or "Чернила";
        local level = data and data[3] or 0;
        if level < 1 then
            return {group=pigment and 10000 or 9999,rank=0,title=title .. " — уровень неизвестен"};
        end
        local band = math.floor((level - 1) / 20);
        -- Keep inks and pigments of the same grade next to one another.
        return {group=band*2+(pigment and 2 or 1),rank=level*10+data[4],
            title=title .. " — уровень предмета " .. (band*20+1) .. "-" .. (band*20+20)};
    end
    if self.category == "enchanting" then
        local rank = self.enchantRanks[item.id] or {group=5,rank=0};
        return {group=rank.group,rank=rank.rank,title=self.enchantGroups[rank.group].title};
    end
    local data = self.materialData and self.materialData[item.id];
    if not data or data[1] ~= self.category then return {group=999,rank=0,title="Прочее"}; end
    local titles = self.materialGroups and self.materialGroups[self.category];
    if titles then return {group=data[2],rank=data[3]*10+data[4],title=titles[data[2]]}; end
    local level = data[3];
    if level < 1 then return {group=998,rank=0,title="Без уровня предмета"}; end
    local band = math.floor((level - 1) / 20);
    return {group=band+1,rank=level*10+data[4],
        title="Уровень предмета " .. (band*20+1) .. "-" .. (band*20+20)};
end

