function P:BankRank(item)
    local slot = self.bankSlots[item.bankEquipLoc];
    local title = slot and slot[2] or item.bankSubType or item.bankType or "Не определено";
    return {group=slot and string.format("%02d",slot[1]) or ("99:" .. title),title=title};
end

function P:BankCluster(item)
    if item.bankEquipLoc == "INVTYPE_FINGER" or item.bankEquipLoc == "INVTYPE_NECK"
        or item.bankEquipLoc == "INVTYPE_TRINKET" then return "Украшения"; end
    -- Broad equipment blocks in All; detailed equipment slots remain inside categories.
    if self.bankSlots[item.bankEquipLoc] then return item.bankType or "Экипировка"; end
    return item.bankSubType or item.bankType or "Не определено";
end

function P:BankClusterLayout(items, columns)
    local groups, ordered = {}, {};
    for _, item in ipairs(items) do
        local title = self:BankCluster(item);
        if not groups[title] then
            groups[title] = {title=title,items={}}; ordered[#ordered+1] = groups[title];
        end
        local group = groups[title]; group.items[#group.items+1] = item;
    end
    table.sort(ordered,function(a,b) return a.title < b.title; end);
    local heights, entries, headers, total = {}, {}, {}, 0;
    for c=1,columns do heights[c]=0; end
    for _,group in ipairs(ordered) do
        -- Measure labels so adjacent blocks cannot overwrite one another.
        self.clusterMeasure:SetText(group.title);
        local labelColumns=math.ceil(((self.clusterMeasure:GetStringWidth() or 100)+8)/41);
        local width=math.min(columns,math.max(labelColumns,math.min(#group.items,math.ceil(columns/2))));
        local bestX,bestY=1,nil;
        for x=1,columns-width+1 do
            local y=0;
            for c=x,x+width-1 do y=math.max(y,heights[c]); end
            if not bestY or y<bestY then bestX,bestY=x,y; end
        end
        local height=20+math.ceil(#group.items/width)*41+8;
        headers[#headers+1]={title=group.title,x=(bestX-1)*41,y=bestY,width=width*41-8,bottom=bestY+height-8};
        for i,item in ipairs(group.items) do
            entries[#entries+1]={item=item,x=(bestX-1+(i-1)%width)*41,y=bestY+20+math.floor((i-1)/width)*41};
        end
        for c=bestX,bestX+width-1 do heights[c]=bestY+height; end
        total=math.max(total,bestY+height);
    end
    return entries,headers,total;
end

function P:SaveWindow()
    local db = self:Context(); local key = self.mode == "bank" and "bankWindow" or "window";
    local frame = self.frame;
    local x,y = frame:GetCenter(); local px,py = UIParent:GetCenter(); local scale=frame:GetScale();
    db[key] = db[key] or {};
    db[key].width,db[key].height = frame:GetWidth(),frame:GetHeight();
    db[key].x,db[key].y = x-px/scale,y-py/scale;
end

function P:RestoreWindow()
    local bank = self.mode == "bank"; local db=self:Context();
    local config = (bank and db.bankWindow or (not bank and db.window)) or {};
    local frame=self.frame;
    frame:SetMinResize(bank and 560 or 780,bank and 420 or 620);
    self.refreshing=true;
    frame:SetWidth(math.max(bank and 560 or 780,math.min(1260,tonumber(config.width) or (bank and 700 or 940))));
    frame:SetHeight(math.max(bank and 420 or 620,math.min(900,tonumber(config.height) or (bank and 480 or 620))));
    frame:ClearAllPoints(); frame:SetPoint("CENTER",UIParent,"CENTER",tonumber(config.x) or 0,tonumber(config.y) or 0);
    frame:SetScale(math.min(1,(UIParent:GetWidth()-30)/frame:GetWidth(),(UIParent:GetHeight()-30)/frame:GetHeight()));
    self.refreshing=nil;
end

function P:SortMode()
    local db = self:Context();
    if self.mode == "bank" then
        if self.category == "all" then return db.bankAllSort or "group"; end
        return db.bankSort or "group";
    end
    return db.categorySort and db.categorySort[self.category]
        or (self.category == "enchanting" and db.enchantSort) or "grade";
end

function P:DisplayRows(items, columns, grouped)
    local result, row, lastGroup = {}, nil, nil;
    for _, item in ipairs(items) do
        local rank = grouped and (self.mode == "bank" and self:BankRank(item) or self:MaterialRank(item));
        local group = rank and rank.group or 0;
        if not row or #row.items >= columns or group ~= lastGroup then
            row = { items = {}, title = rank and rank.title or nil };
            result[#result + 1] = row;
        end
        row.items[#row.items + 1] = item; lastGroup = group;
    end
    return result;
end

function P:Button(parent, text, width, callback)
