function P:Open(mode)
    self:CreateUI();
    self:RecoverIcons();
    self.iconRetryUntil, self.iconRetryAt = GetTime() + 10, GetTime() + 0.5;
    -- Switching the saved view does not end the NPC session or its active operation.
    if self.windowReady then self:SaveWindow(); end
    self.mode, self.category, self.rowOffset = mode or "ling", "all", 0;
    self.categoryOffset = 0;
    self:RestoreWindow(); self.windowReady = true;
    self.selected = nil;
    if mode == "bank" and self.atBank then self:CaptureBank(); end
    self.frame:Show(); self:Refresh();
end

