function P:ShowBankCharacters()
    if not self.characterMenu then self.characterMenu=CreateFrame("Frame","PikaBankCharactersMenu",UIParent,"UIDropDownMenuTemplate"); end
    UIDropDownMenu_Initialize(self.characterMenu,function()
        local _,selected=P:ViewedBank();
        for _,entry in ipairs(P:BankCharacters()) do
            local info=UIDropDownMenu_CreateInfo(); local key=entry.key;
            info.text=entry.text; info.checked=key==selected;
            info.func=function() P:SelectBankCharacter(key); end;
            UIDropDownMenu_AddButton(info);
        end
    end,"MENU");
    ToggleDropDownMenu(1,nil,self.characterMenu,self.characterButton,0,0);
end

function P:RefreshBankBags()
    if not self.bankBagPanel or not self.bankBagPanel:IsShown() then return; end
    local bank=self:ViewedBank();
    for number,b in ipairs(self.bankBagButtons) do
        local bag=bank and bank.bags and bank.bags[number]; b.bag=bag;
        b.icon:SetTexture(bag and bag.texture or "Interface\\PaperDoll\\UI-PaperDoll-Slot-Bag");
        local tint=bag and bag.purchased and 1 or 0.35; b.icon:SetVertexColor(tint,tint,tint);
        b.count:SetText(bag and bag.slots and bag.slots>0 and tostring(bag.slots) or "");
    end
    self.bankBagHint:SetText(self:CanChangeBankBags() and "Перенесите сюда новую сумку из рюкзака."
        or "Сохранённый просмотр. Замена — своим персонажем у банкира.");
end

