function P:Refresh()
    if not self.frame or not self.status or not self.frame:IsShown() or self.refreshing then return; end
    self.refreshing = true;
    local db = self:Context();
    local index;
    if self.mode == "ling" then index = self:Index(); else index = self:ViewedBank(); end
    local items = index and index.items or {};
    if self.mode == "ling" and self.selected then self.selected = self:FindItem(self.selected.id); end
    local categories = { { key = "all", text = "Все" } };
    local bankCategories = {};
    if self.mode == "ling" then
        for _, category in ipairs(index and index.categories or {}) do categories[#categories + 1] = category; end
        local position = #categories + 1;
        for i, category in ipairs(categories) do if category.key == "parts" then position = i + 1; break end end
        table.insert(categories, position, {key="viewer_inks",text="Чернила и пигменты"});
    else
        local seen, typed = {}, {};
        for _, item in ipairs(items) do
            local key, label = self:BankItemCategory(item);
            bankCategories[item] = { key = key, text = label };
            if (item.amount or 0) > 0 and not seen[key] then
                seen[key] = true; typed[#typed + 1] = { key = key, text = label };
            end
        end
        table.sort(typed, function(a, b)
            if a.key == "bank_unknown" then return false; end
            if b.key == "bank_unknown" then return true; end
            return a.text < b.text;
        end);
        for _, category in ipairs(typed) do categories[#categories + 1] = category; end
        if self.category ~= "all" and not seen[self.category] then self.category, self.rowOffset = "all", 0; end
    end
    local bank = self.mode == "bank";
    if bank then
        local _,key,character=self:ViewedBank();
        self.characterButton:SetText(character.name or key:match("([^:]+)$") or key);
        self.characterButton:Show(); self.bankBagsToggle:Show(); self:RefreshBankBags();
    else self.characterButton:Hide(); self.bankBagsToggle:Hide(); self.bankBagPanel:Hide(); end
    local bottom = bank and 75 or 145;
    local visibleCategories = math.min(20,math.max(1,math.floor((self.frame:GetHeight()-112-bottom)/22)));
    self.categoryPane:SetHeight(visibleCategories*22);
    self.categoryMaxOffset=math.max(0,#categories-visibleCategories);
    self.categoryOffset=math.min(self.categoryOffset or 0,self.categoryMaxOffset);
    local filtered = {};
    local query = self.search:GetText() or "";
    local searching = self.mode == "ling" and string.find(query, "%S") ~= nil;
    local matches, counted = { all = 0 }, {};
    for _, item in ipairs(items) do
        local categoryKey = bankCategories[item] and bankCategories[item].key or self:DisplayCategory(item);
        local categoryText = bankCategories[item] and (bankCategories[item].text .. " " .. (item.bankSubType or "")) or item.category or "";
        if self.mode == "ling" and categoryKey == "viewer_inks" then
            categoryText = categoryText .. (self.pigmentIDs[item.id] and " Пигменты" or " Чернила");
        end
        if (item.amount or 0) > 0 then
            local name = item.name or GetItemInfo(item.id) or tostring(item.id);
            if RS:Matches({ name = name .. " " .. item.id, category = categoryText }, query) then
                if searching and not counted[item.id] then
                    counted[item.id] = true;
                    matches.all = matches.all + 1;
                    if categoryKey then matches[categoryKey] = (matches[categoryKey] or 0) + 1; end
                end
                if self.category == "all" or categoryKey == self.category then
                    filtered[#filtered + 1] = item;
                end
            end
        end
    end
    -- Count across the full snapshot; selecting a category only filters the grid.
    local categoryWidth = self.normalCategoryWidth;
    local categoryLabels = {};
    for _, category in ipairs(categories) do
        local label = self.labels[category.key] or category.text;
        local count = matches[category.key] or 0;
        if searching and (count > 0 or category.key == "all") then
            label = label .. " (" .. count .. ")";
        end
        categoryLabels[category.key] = label;
        if searching then
            self.categoryMeasure:SetText("> " .. label);
            categoryWidth = math.max(categoryWidth, math.ceil((self.categoryMeasure:GetStringWidth() or 100) + 16));
        end
    end
    self.categoryWidth = categoryWidth;
    self.gridLeft = 20 + categoryWidth + 12;
    self.categoryPane:SetWidth(categoryWidth);
    for i, button in ipairs(self.categoryButtons) do
        local category = i <= visibleCategories and categories[i+self.categoryOffset];
        if category then
            button.key = category.key;
            local label = (category.key == self.category and "> " or "") .. categoryLabels[category.key];
            if searching and (matches[category.key] or 0) > 0 then
                label = "|cff80dfff" .. label .. "|r";
            end
            button:SetWidth(categoryWidth);
            button:SetText(label);
            button:Show();
        else button:Hide(); end
    end
    local enchant = bank or self.category ~= "all";
    local sortMode=self:SortMode();
    local grouped = bank and sortMode == "group" or (not bank and enchant and sortMode ~= "name");
    if enchant then
        self.sortButton:Show(); self.sortButton:SetText(bank and ({group="По слотам",level="По уровню",name="По имени",slots="Как в банке"})[sortMode] or (grouped and "По грейду" or "По имени"));
    else self.sortButton:Hide(); end
    if bank and self.category == "all" and grouped then self.sortButton:SetText("Блоки"); end
    if grouped then
        self.sortHint:SetText(self.category == "enchanting" and "Слева направо: от младших к старшим"
            or "Слева направо: по уровню предмета");
        self.sortHint:Show();
    else self.sortHint:Hide(); end
    if bank then self.sortHint:Hide(); end
    self.grid:ClearAllPoints();
    self.grid:SetPoint("TOPLEFT", self.frame, "TOPLEFT", self.gridLeft, enchant and -142 or -112);
    self.grid:SetPoint("BOTTOMRIGHT", self.frame, "BOTTOMRIGHT", -43, bottom);
    self.scroll:ClearAllPoints();
    self.scroll:SetPoint("TOPRIGHT",self.frame,"TOPRIGHT",-25,enchant and -162 or -132);
    self.scroll:SetPoint("BOTTOMRIGHT",self.frame,"BOTTOMRIGHT",-25,bottom+21);
    self.status:ClearAllPoints();
    self.status:SetPoint("BOTTOMLEFT",self.frame,"BOTTOMLEFT",bank and 22 or math.max(self.gridLeft,244),bank and 40 or 110);
    self.status:SetPoint("BOTTOMRIGHT",self.frame,"BOTTOMRIGHT",-30,bank and 40 or 110);
    self.search:ClearAllPoints();
    self.search:SetPoint("TOPLEFT",self.frame,"TOPLEFT",262,-50);
    self.search:SetPoint("TOPRIGHT",self.frame,"TOPRIGHT",bank and -24 or -158,-50);
    if bank then self.depositButton:Hide(); self.takeAll:Hide(); self.refreshButton:Hide();
    else self.depositButton:Show(); self.takeAll:Show(); self.refreshButton:Show(); end
    self.stopButton:ClearAllPoints();
    if bank then self.stopButton:SetPoint("BOTTOMLEFT",self.frame,"BOTTOMLEFT",22,12);
    else self.stopButton:SetPoint("LEFT",self.takeAll,"RIGHT",12,0); end
    self.help:ClearAllPoints(); self.help:SetPoint("BOTTOMRIGHT",self.frame,"BOTTOMRIGHT",-35,bank and 16 or 31);
    table.sort(filtered, function(a, b)
        if self.mode == "bank" then
            if sortMode == "slots" then
                if a.bag == b.bag then return a.slot < b.slot; end; return a.bag < b.bag;
            end
            if grouped then
                local ar,br=self:BankRank(a),self:BankRank(b);
                if ar.group ~= br.group then return ar.group < br.group; end
            end
            if sortMode ~= "name" and (a.bankLevel or 0) ~= (b.bankLevel or 0) then
                return (a.bankLevel or 0) > (b.bankLevel or 0);
            end
        end
        if grouped and not bank then
            local ar, br = self:MaterialRank(a), self:MaterialRank(b);
            if ar.group ~= br.group then return ar.group < br.group; end
            if ar.rank ~= br.rank then return ar.rank < br.rank; end
        end
        local an, bn = a.name or tostring(a.id), b.name or tostring(b.id);
        if an == bn then return a.id < b.id; end
        return an < bn;
    end);
    local columns = math.max(1, math.floor((self.frame:GetWidth() - self.gridLeft - 47) / 41));
    local step = grouped and 61 or 41;
    local rows = math.max(1, math.floor((self.frame:GetHeight() - 112 - bottom - (enchant and 30 or 0)) / step));
    local clusters = bank and self.category == "all" and grouped;
    local entries, headers, contentHeight = {}, {}, 0;
    local viewport = self.frame:GetHeight()-112-bottom-(enchant and 30 or 0);
    local scrollStep = clusters and 41 or step;
    if clusters then
        entries,headers,contentHeight=self:BankClusterLayout(filtered,columns);
        self.maxOffset=math.max(0,math.ceil((contentHeight-viewport)/scrollStep));
    else
        local displayRows=self:DisplayRows(filtered,columns,grouped);
        self.maxOffset=math.max(0,#displayRows-rows);
        for r,row in ipairs(displayRows) do
            if row.title then headers[#headers+1]={title=row.title,x=0,y=(r-1)*step,width=columns*41}; end
            for c,item in ipairs(row.items) do
                entries[#entries+1]={item=item,x=(c-1)*41,y=(r-1)*step+(grouped and 20 or 0)};
            end
        end
        viewport=rows*step;
    end
    self.rowOffset = math.max(0, math.min(self.rowOffset or 0, self.maxOffset));
    self.scroll:SetMinMaxValues(0, self.maxOffset); self.scroll:SetValue(self.rowOffset);
    if self.maxOffset > 0 then self.scroll:Show(); else self.scroll:Hide(); end
    self.missingIcons = nil;
    for _, header in ipairs(self.rowHeaders) do header:Hide(); end
    local offset=self.rowOffset*scrollStep;
    local headerCount=0;
    for _,entry in ipairs(headers) do
        local y=entry.y-offset;
        if y>=0 and y+16<=viewport then
            headerCount=headerCount+1;
            local header=self.rowHeaders[headerCount] or self:Font(self.grid,"GameFontNormalSmall");
            self.rowHeaders[headerCount]=header; header:ClearAllPoints();
            header:SetPoint("TOPLEFT",self.grid,"TOPLEFT",entry.x,-y);
            header:SetWidth(entry.width); header:SetHeight(16); header:SetWordWrap(false);
            header:SetText(entry.title); header:Show();
        end
    end
    local shown=0;
    for _,entry in ipairs(entries) do
        local y=entry.y-offset;
        if y>=0 and y+37<=viewport then
            shown=shown+1;
            local b=self:ItemButton(shown); local item=entry.item;
            b.item=item; b:ClearAllPoints();
            b:SetPoint("TOPLEFT",self.grid,"TOPLEFT",entry.x,-y);
            local _, _, _, _, _, _, _, _, _, texture = GetItemInfo(item.id);
            texture = item.texture or texture or (GetItemIcon and GetItemIcon(item.id));
            if not texture then self.missingIcons = true; end
            b.icon:SetTexture(texture or "Interface\\Icons\\INV_Misc_QuestionMark");
            b.count:SetText("x" .. tostring(item.amount));
            b.icon:SetVertexColor(1, 1, 1);
            if self.selected == item then b.selection:Show(); else b.selection:Hide(); end
            b:Show();
        end
    end
    for i = shown + 1, math.max(#self.itemButtons,columns*rows) do
        local button=self:ItemButton(i); button.item=nil; button:Hide();
    end
    self.title:SetText(self.mode == "ling" and "Ling — хранилище ресурсов" or "Личный банк — сохранённый просмотр");
    local checked = index and (index.viewerUpdatedAt or index.updatedAt or index.scannedAt);
    local status = checked and ("Последний полный снимок: " .. date("%d.%m %H:%M", checked)) or "Снимок ещё не создан";
    if self.mode == "ling" then
        status = (self.online and "Ling доступен. " or "Просмотр вдали от Ling. ") .. status;
        if index and index.viewerStale then status = status .. " | Требуется сверка"; end
    end
    self.subtitle:SetText(status .. " | Показано: " .. #filtered);
    if bank then
        local _,key=self:ViewedBank(); self.subtitle:SetText(key .. " | " .. status .. " | Показано: " .. #filtered);
    end
    self.emptyText:SetText(#filtered == 0 and (not index and (self.mode == "ling"
        and "Откройте Ling: хранилище будет просканировано автоматически."
        or "Один раз посетите обычного банкира, чтобы сохранить содержимое банка.") or "В этой категории ничего не найдено.") or "");
    local botJob = self.BotDeposit and self.BotDeposit.job;
    local busy = RS.scan and "Обновление: " .. (RS.status or "сканирование...") or self.notice;
    if botJob then
        busy = self.notice .. (RS.scan and (" " .. (RS.status or "Сканирование банка...")) or "");
    end
    self.status:SetText((self.mode == "ling" and (busy or "Выберите ресурс. ПКМ получает одну порцию.")
        or (self.online and (RS:IsBusy() or self.op or self.scanAt or #self.queue > 0 or (self.BotDeposit and self.BotDeposit.job))
            and ("Ling в фоне: " .. (busy or "выполняется операция"))
            or "Сохранённые предметы доступны для просмотра. Перемещение — у обычного банкира."))
        .. (self.mode == "ling" and #self.queue > 0 and (" | В очереди: " .. #self.queue) or ""));
    if self.mode == "ling" then self.botsButton:Show(); else self.botsButton:Hide(); end
    self.botsButton:SetText(botJob and ("Альт " .. botJob.index .. "/" .. #botJob.bots .. ": проверка") or "Альты: сдать по одному");
    if self.mode == "ling" and self.online and not self:Combat() and not botJob
            and not RS.navigation and not self.op and not self.deposit and #self.queue == 0 then
        self.botsButton:Enable(); else self.botsButton:Disable(); end
    local active = self.mode == "ling" and self.online and not self:Combat() and not botJob;
    if active then self.depositButton:Enable(); self.refreshButton:Enable(); else self.depositButton:Disable(); self.refreshButton:Disable(); end
    if active and self.selected and (self.selected.amount or 0) > 0 and not self.deposit then
        self.takeAll:Enable(); self.takeStacks:Enable();
    else self.takeAll:Disable(); self.takeStacks:Disable(); end
    if self.mode == "ling" then self.stackControls:Show(); else self.stackControls:Hide(); end
    local amount, size = self:StackPreview(self.selected, self.stackInput:GetText());
    self.stackPreview:SetText(self.selected and ((self.selected.name or tostring(self.selected.id)) .. "\n"
        .. (amount and (amount .. " шт. из " .. (self.selected.amount or 0) .. " (пачка: " .. size .. ")")
        or "Размер пачки ещё не загружен")) or "Выберите ресурс в сетке");
    if self.online and (RS:IsBusy() or self.op or self.scanAt or #self.queue > 0 or (self.BotDeposit and self.BotDeposit.job)) then self.stopButton:Enable(); else self.stopButton:Disable(); end
    if not bank or (self.online and (RS:IsBusy() or self.op or self.scanAt or #self.queue > 0 or (self.BotDeposit and self.BotDeposit.job))) then self.stopButton:Show(); else self.stopButton:Hide(); end
    self.help:SetText(self.mode == "ling" and "ЛКМ: выбрать   ПКМ: получить порцию" or "Просмотр сохранённого банка");
    self.refreshing = nil;
end
